NF_REVISION = '"""\nnf_revision.py -- extended experiments of the manuscript.\n\nBuilds on nf_tune.py (same feature transform, same validation-only selection,\nsame stratified split) and adds every arm the reviews ask for:\n\n  R2/R4  loss       --loss mse | huber,  --kappa <float> | auto  (auto = (alpha+1)*lambda_max,\n                    i.e. every target stays in the quadratic regime), --alpha <float>\n  R2/R4  sampler    none | frozen (the original single bootstrap) | epoch (redrawn every epoch)\n                    + number of UNIQUE training flows seen per class\n  R2/R4  control    the same 2x2 with class-weighted cross-entropy (weights -log pi_c)\n  R2/R4  metrics    per-family one-vs-rest AUPRC, binary AUROC / AUPRC (threshold-free)\n  R2/R4  recalib.   per-class additive offsets tuned on VALIDATION for macro-F1, then\n                    applied once to test; CE + post-hoc logit adjustment (tau tuned on val)\n  R2     mechanism  for value-head runs with the plain reward, the population-minimiser\n                    rescaling argmax_a lambda_a (Q_a + 1) is scored as a derived condition,\n                    and test predictions are saved so agreement with RB can be computed\n  R4     seeds      any number of training seeds (use 10-20)\n\nMethod names:  <head>-<weight>-<sampler>\n    head    val  (one-step full-information value regression, Eq. 7)\n            ce   (cross-entropy)\n    weight  plain | freq   (val: reward lambda_c = 1 or -log pi_c;\n                            ce : sample weight 1 or -log pi_c)\n    sampler none | frozen | epoch\n  e.g.  val-plain-none = PU,  val-freq-none = RU,  val-plain-epoch = PB (per-epoch),\n        val-freq-epoch = RB (per-epoch),  ce-freq-epoch = weighted CE + balanced sampler.\n  Trees: extra_trees | rf | xgboost  (validation-tuned, as in nf_tune.py)\n\nUsage\n    python src/nf_revision.py --processed data/processed --dataset nf_unsw \\\n        --methods val-plain-none val-freq-none val-plain-epoch val-freq-epoch \\\n        --loss mse --alpha 5 --seeds 42 7 13 99 123 2024 31 57 88 101 \\\n        --save-preds results/preds --out results/rev_nf_unsw_mse.json\n"""\nimport argparse\nimport json\nimport os\nimport sys\nimport time\n\nimport numpy as np\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nfrom nf_tune import GRIDS, K, build_transform, fit_tree, full_metrics, macro_recall_supported  # noqa: E402\n\nTREES = ("extra_trees", "rf", "xgboost")\n\n\n# ------------------------------------------------------------------ helpers\ndef parse_method(m):\n    if m in TREES:\n        return None\n    head, weight, sampler = m.split("-")\n    assert head in ("val", "ce", "bandit") and weight in ("plain", "freq") \\\n        and sampler in ("none", "frozen", "epoch", "iw"), m\n    return head, weight, sampler\n\n\ndef class_stats(y):\n    counts = np.bincount(y, minlength=K).astype(float)\n    N = counts.sum()\n    pi = counts / N\n    lam = np.where(counts > 0, -np.log(np.where(pi > 0, pi, 1.0)), 1.0)\n    return counts, pi, lam\n\n\ndef draw(rs, y, counts):\n    """Class-balanced bootstrap of size N: p_i proportional to 1/N_{y_i}."""\n    w = np.where(counts[y] > 0, 1.0 / counts[y], 0.0)\n    return rs.choice(len(y), size=len(y), replace=True, p=w / w.sum())\n\n\ndef macro_f1(y, p):\n    vals = []\n    for c in range(K):\n        m = y == c\n        if not m.sum():\n            continue\n        tp = ((p == c) & m).sum(); fp = ((p == c) & ~m).sum(); fn = ((p != c) & m).sum()\n        pr = tp / (tp + fp) if tp + fp else 0.0\n        rc = tp / (tp + fn)\n        vals.append(2 * pr * rc / (pr + rc) if pr + rc else 0.0)\n    return float(np.mean(vals))\n\n\ndef threshold_free(y, S):\n    """S: (n, K) scores (logits or Q values; both rank-valid per column)."""\n    from sklearn.metrics import average_precision_score, roc_auc_score\n    auprc = []\n    for c in range(K):\n        yc = (y == c).astype(int)\n        auprc.append(float(average_precision_score(yc, S[:, c])) if 0 < yc.sum() < len(y) else None)\n    sup = [v for v in auprc if v is not None]\n    # binary attack score: best attack action minus the Normal action\n    a = S[:, 1:].max(axis=1) - S[:, 0]\n    yb = (y != 0).astype(int)\n    from sklearn.metrics import roc_curve\n    fpr, tpr, _ = roc_curve(yb, a)\n    at = {f"recall_at_fpr_{f:g}": float(np.max(tpr[fpr <= f])) if np.any(fpr <= f) else 0.0\n          for f in (1e-3, 1e-2)}\n    return {"per_class_auprc": auprc,\n            "macro_auprc": float(np.mean(sup)),\n            "binary_auroc": float(roc_auc_score(yb, a)),\n            "binary_auprc": float(average_precision_score(yb, a)), **at}\n\n\ndef tune_offsets(yva, Sva, passes=3, npts=41):\n    """Per-class additive offsets (Normal fixed at 0) maximising val macro-F1."""\n    b = np.zeros(K)\n    span = 3.0 * float(np.std(Sva)) + 1e-6\n    grid = np.linspace(-span, span, npts)\n    best = macro_f1(yva, np.argmax(Sva, 1))\n    for _ in range(passes):\n        for c in range(1, K):\n            keep = b[c]\n            for g in grid:\n                b[c] = g\n                s = macro_f1(yva, np.argmax(Sva + b, 1))\n                if s > best + 1e-6:\n                    best, keep = s, g\n            b[c] = keep\n    return b, best\n\n\ndef tune_logit_adjust(yva, Zva, pi):\n    """Post-hoc logit adjustment z_a - tau log pi_a (Menon et al. 2021), tau on val."""\n    lp = np.log(np.where(pi > 0, pi, 1.0))\n    best = (-1.0, 0.0)\n    for tau in np.arange(0.0, 2.01, 0.25):\n        s = macro_recall_supported(yva, np.argmax(Zva - tau * lp, 1))\n        if s > best[0] + 1e-6:\n            best = (s, float(tau))\n    return best[1], lp\n\n\n# ------------------------------------------------------------------ model\ndef build_net(d, width, lr):\n    from tensorflow import keras\n    net = keras.Sequential([\n        keras.layers.Input(shape=(d,)),\n        keras.layers.Dense(width, activation="relu"),\n        keras.layers.BatchNormalization(),\n        keras.layers.Dropout(0.3),\n        keras.layers.Dense(width // 2, activation="relu"),\n        keras.layers.Dropout(0.2),\n        keras.layers.Dense(K),\n    ])\n    return net, keras.optimizers.Adam(lr)\n\n\ndef fit_net(spec, cfg, Xtr, ytr, Xva, yva, seed, args, max_epochs, patience=8):\n    import tensorflow as tf\n    from tensorflow import keras\n    tf.keras.utils.set_random_seed(seed)\n    head, weight, sampler = spec\n    counts, pi, lam = class_stats(ytr)\n    rs = np.random.RandomState(seed)\n\n    net, opt = build_net(Xtr.shape[1], cfg["width"], cfg["lr"])\n    lam_use = lam if weight == "freq" else np.ones(K)\n    kappa = None\n    if head in ("val", "bandit"):\n        alpha = args.alpha\n        R = np.zeros((K, K), np.float32)\n        for c in range(K):\n            R[c, :] = -lam_use[c]; R[c, c] = alpha * lam_use[c]\n        if args.loss == "mse":\n            loss = keras.losses.MeanSquaredError()\n        else:\n            kappa = (alpha + 1) * lam_use.max() if args.kappa == "auto" else float(args.kappa)\n            loss = keras.losses.Huber(delta=kappa)\n    else:\n        loss = keras.losses.SparseCategoricalCrossentropy(from_logits=True)\n    net.compile(opt, loss=loss)\n\n    if head == "bandit":\n        return fit_bandit(net, opt, R, lam_use, spec, Xtr, ytr, Xva, yva, rs, counts, args,\n                          max_epochs, patience, kappa)\n    iw = (len(ytr) / (K * counts[ytr])).astype(np.float32) if sampler == "iw" else None\n    seen = np.zeros(len(ytr), bool)\n    idx = np.arange(len(ytr)) if sampler in ("none", "iw") else draw(rs, ytr, counts)\n    best, best_w, wait, ep_run = -1.0, None, 0, 0\n    for ep in range(max_epochs):\n        if sampler == "epoch" and ep > 0:\n            idx = draw(rs, ytr, counts)          # redraw every epoch\n        seen[idx] = True\n        Xe, ye = Xtr[idx], ytr[idx]\n        if head == "val":\n            net.fit(Xe, R[ye], sample_weight=iw, epochs=1, batch_size=512, verbose=0, shuffle=True)\n        else:\n            sw = lam_use[ye].astype(np.float32)   # -log pi_c weights, or 1\n            if iw is not None:\n                sw = sw * iw\n            net.fit(Xe, ye, sample_weight=sw, epochs=1, batch_size=512, verbose=0, shuffle=True)\n        ep_run = ep + 1\n        s = macro_recall_supported(yva, np.argmax(net.predict(Xva, verbose=0, batch_size=4096), 1))\n        if s > best + 1e-4:\n            best, best_w, wait = s, net.get_weights(), 0\n        else:\n            wait += 1\n            if wait >= patience:\n                break\n    if best_w is not None:\n        net.set_weights(best_w)\n    info = {"epochs_run": ep_run, "kappa": kappa,\n            "unique_seen_per_class": [int(seen[ytr == c].sum()) for c in range(K)],\n            "train_per_class": counts.astype(int).tolist()}\n    return net, best, info\n\n\ndef fit_bandit(net, opt, R, lam_use, spec, Xtr, ytr, Xva, yva, rs, counts, args,\n               max_epochs, patience, kappa, batch=512, buffer_cap=50000,\n               eps_start=1.0, eps_end=0.05, warmup_epochs=5):\n    """Epsilon-greedy contextual bandit with experience replay (reviewer M3 / R2 / R4-3).\n\n    Unlike the full-information value regression, the agent observes ONLY the reward of\n    the action it took, chosen epsilon-greedily from its own Q estimates; transitions\n    (x, a, r) go into a FIFO replay buffer and gradient steps use uniform minibatches\n    from that buffer, updating Q(x, a) for the taken action only.  One-step returns\n    (gamma = 0): with i.i.d. next states the bootstrap term is action-independent and\n    leaves the greedy policy unchanged (Section V).  The sampler controls which flows\n    the agent is shown, exactly as an environment\'s sampling would.\n    """\n    import tensorflow as tf\n    _, weight, sampler = spec\n    loss_fn = (tf.keras.losses.Huber(delta=kappa, reduction="none") if args.loss == "huber"\n               else tf.keras.losses.MeanSquaredError(reduction="none"))\n    Rt = tf.constant(R)\n    iw_all = (len(ytr) / (K * counts[ytr])).astype(np.float32) if sampler == "iw" \\\n        else np.ones(len(ytr), np.float32)\n\n    @tf.function\n    def act(x):\n        return tf.argmax(net(x, training=False), axis=1, output_type=tf.int32)\n\n    @tf.function\n    def step(x, a, r, w):\n        with tf.GradientTape() as tape:\n            q = net(x, training=True)\n            qa = tf.gather(q, a, axis=1, batch_dims=1)\n            l = loss_fn(tf.expand_dims(r, 1), tf.expand_dims(qa, 1))\n            l = tf.reduce_sum(l * w) / tf.reduce_sum(w)\n        g = tape.gradient(l, net.trainable_variables)\n        opt.apply_gradients(zip(g, net.trainable_variables))\n\n    buf_i = np.zeros(buffer_cap, np.int64); buf_a = np.zeros(buffer_cap, np.int32)\n    buf_r = np.zeros(buffer_cap, np.float32); n_buf = 0; ptr = 0\n    seen = np.zeros(len(ytr), bool)\n    idx = np.arange(len(ytr)) if sampler in ("none", "iw") else draw(rs, ytr, counts)\n    steps_per_epoch = int(np.ceil(len(ytr) / batch))\n    total_warm = warmup_epochs * steps_per_epoch\n    t = 0\n    best, best_w, wait, ep_run = -1.0, None, 0, 0\n    for ep in range(max_epochs):\n        if sampler == "epoch" and ep > 0:\n            idx = draw(rs, ytr, counts)\n        order = rs.permutation(idx)\n        seen[order] = True\n        for b in range(steps_per_epoch):\n            ib = order[b * batch:(b + 1) * batch]\n            if len(ib) == 0:\n                continue\n            eps = max(eps_end, eps_start - (eps_start - eps_end) * t / max(1, total_warm))\n            greedy = act(tf.constant(Xtr[ib])).numpy()\n            explore = rs.rand(len(ib)) < eps\n            a = np.where(explore, rs.randint(0, K, len(ib)), greedy).astype(np.int32)\n            r = R[ytr[ib], a]                                   # reward of the taken action only\n            for j in range(len(ib)):                            # FIFO replay buffer\n                buf_i[ptr] = ib[j]; buf_a[ptr] = a[j]; buf_r[ptr] = r[j]\n                ptr = (ptr + 1) % buffer_cap\n            n_buf = min(buffer_cap, n_buf + len(ib))\n            sel = rs.randint(0, n_buf, batch)\n            xi = buf_i[sel]\n            step(tf.constant(Xtr[xi]), tf.constant(buf_a[sel]), tf.constant(buf_r[sel]),\n                 tf.constant(iw_all[xi]))\n            t += 1\n        ep_run = ep + 1\n        s = macro_recall_supported(yva, np.argmax(net.predict(Xva, verbose=0, batch_size=4096), 1))\n        if s > best + 1e-4:\n            best, best_w, wait = s, net.get_weights(), 0\n        elif ep >= warmup_epochs:                                # no early stop during exploration warm-up\n            wait += 1\n            if wait >= patience:\n                break\n    if best_w is not None:\n        net.set_weights(best_w)\n    info = {"epochs_run": ep_run, "kappa": kappa, "bandit": {"eps_end": eps_end, "buffer": buffer_cap,\n            "warmup_epochs": warmup_epochs},\n            "unique_seen_per_class": [int(seen[ytr == c].sum()) for c in range(K)],\n            "train_per_class": counts.astype(int).tolist()}\n    return net, best, info\n\n\n# ------------------------------------------------------------------ main\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--processed", required=True)\n    ap.add_argument("--dataset", required=True)\n    ap.add_argument("--methods", nargs="+", required=True)\n    ap.add_argument("--seeds", nargs="+", type=int,\n                    default=[42, 7, 13, 99, 123, 2024, 31, 57, 88, 101])\n    ap.add_argument("--loss", choices=["mse", "huber"], default="mse")\n    ap.add_argument("--kappa", default="1.0", help="Huber threshold, or \'auto\'")\n    ap.add_argument("--alpha", type=float, default=5.0)\n    ap.add_argument("--max-epochs", type=int, default=60)\n    ap.add_argument("--grid", choices=["full", "fixed", "wide"], default="full",\n                    help="fixed = width 256, lr 1e-3 (cheap sweeps); wide = width {256,512,1024} x "\n                         "lr {1e-3,3e-4,1e-4} (reviewer Mo6)")\n    ap.add_argument("--val-frac", type=float, default=0.2)\n    ap.add_argument("--save-preds", default=None)\n    ap.add_argument("--tag", default="", help="suffix for saved prediction files (keeps runs apart)")\n    ap.add_argument("--out", required=True)\n    a = ap.parse_args()\n\n    P = a.processed\n    Xtr_all = np.load(f"{P}/{a.dataset}_train.X.npy"); ytr_all = np.load(f"{P}/{a.dataset}_train.y.npy")\n    Xte = np.load(f"{P}/{a.dataset}_test.X.npy"); yte = np.load(f"{P}/{a.dataset}_test.y.npy")\n    feats = json.load(open(f"{P}/{a.dataset}_train.meta.json"))["features"]\n    # values beyond float32 range became +-inf when prepare_nf cast to float32; apply the\n    # same policy prepare_nf uses for non-finite inputs (set to 0). No-op on finite data.\n    n_bad = int((~np.isfinite(Xtr_all)).sum() + (~np.isfinite(Xte)).sum())\n    if n_bad:\n        print(f"  [{a.dataset}] {n_bad} non-finite feature values set to 0", flush=True)\n        Xtr_all = np.nan_to_num(Xtr_all, nan=0.0, posinf=0.0, neginf=0.0)\n        Xte = np.nan_to_num(Xte, nan=0.0, posinf=0.0, neginf=0.0)\n\n    tag = {"loss": a.loss, "kappa": a.kappa if a.loss == "huber" else None, "alpha": a.alpha}\n    os.makedirs(os.path.dirname(a.out) or ".", exist_ok=True)\n    if a.save_preds:\n        os.makedirs(a.save_preds, exist_ok=True)\n    results = json.load(open(a.out)) if os.path.exists(a.out) else []\n    done = {(r["method"], r["seed"]) for r in results}\n\n    for seed in a.seeds:\n        rng = np.random.RandomState(seed)\n        tr, va = [], []\n        for c in np.unique(ytr_all):\n            ix = np.where(ytr_all == c)[0]; rng.shuffle(ix)\n            n_va = max(1, int(round(len(ix) * a.val_frac)))\n            va.extend(ix[:n_va]); tr.extend(ix[n_va:])\n        tr, va = np.array(tr), np.array(va)\n        ytr, yva = ytr_all[tr], ytr_all[va]\n        tfn, dim, _ = build_transform(Xtr_all[tr], feats)\n        _, pi, lam = class_stats(ytr)\n\n        for method in a.methods:\n            if (method, seed) in done:\n                continue\n            spec = parse_method(method)\n            t0 = time.time()\n            rec = {"dataset": a.dataset, "method": method, "seed": seed, **tag}\n\n            if spec is None:                                  # tree baselines\n                best = (-1.0, None, None)\n                for cfg in GRIDS[method]:\n                    m = fit_tree(method, cfg, Xtr_all[tr], ytr, seed)\n                    s = macro_recall_supported(yva, m.predict(Xtr_all[va]))\n                    if s > best[0]:\n                        best = (s, cfg, m)\n                s, cfg, m = best\n                P_ = m.predict_proba(Xte)                      # columns = m.classes_ only\n                Ste = np.full((len(Xte), K), -1.0)             # absent classes never win\n                Ste[:, np.asarray(m.classes_, int)] = P_\n                rec.update({"selected_config": cfg, "val_macro_recall": s})\n                rec.update(full_metrics(yte, np.argmax(Ste, 1)))\n                rec["threshold_free"] = threshold_free(yte, Ste)\n                if a.save_preds:\n                    np.save(f"{a.save_preds}/{a.dataset}_{method}_{a.loss}{a.tag}_s{seed}.npy",\n                            np.argmax(Ste, 1).astype(np.int8))\n            else:\n                Atr, Ava, Ate = tfn(Xtr_all[tr]), tfn(Xtr_all[va]), tfn(Xte)\n                grid = {"full": GRIDS["_net"], "fixed": [{"width": 256, "lr": 1e-3}],\n                        "wide": [{"width": w, "lr": lr} for w in (256, 512, 1024)\n                                 for lr in (1e-3, 3e-4, 1e-4)]}[a.grid]\n                best = (-1.0, None, None, None)\n                for cfg in grid:                              # SELECT ON VALIDATION\n                    net, s, info = fit_net(spec, cfg, Atr, ytr, Ava, yva, seed, a, a.max_epochs)\n                    print(f"  [{method} seed={seed}] {cfg} -> val {s:.4f} ({info[\'epochs_run\']} ep)",\n                          flush=True)\n                    if s > best[0]:\n                        best = (s, cfg, net, info)\n                s, cfg, net, info = best\n                Sva = net.predict(Ava, verbose=0, batch_size=4096)\n                Ste = net.predict(Ate, verbose=0, batch_size=4096)\n                yp = np.argmax(Ste, 1)\n                rec.update({"selected_config": cfg, "val_macro_recall": s, **info})\n                rec.update(full_metrics(yte, yp))                     # argmax operating point\n                rec["threshold_free"] = threshold_free(yte, Ste)\n\n                b, vf1 = tune_offsets(yva, Sva)                        # recalibrated on val\n                rec["recalibrated"] = {"offsets": b.tolist(), "val_macro_f1": vf1,\n                                       **full_metrics(yte, np.argmax(Ste + b, 1))}\n\n                head, weight, sampler = spec\n                if head == "ce" and weight == "plain" and sampler == "none":\n                    tau, lp = tune_logit_adjust(yva, Sva, pi)          # logit-adjust baseline\n                    rec["logit_adjusted"] = {"tau": tau, **full_metrics(yte, np.argmax(Ste - tau * lp, 1))}\n                if head in ("val", "bandit") and weight == "freq" and a.loss == "mse":\n                    # post-hoc prior correction (reviewer Mo3): under squared loss\n                    # Q_a + C(x) = (alpha+1) lambda_a P_q(a|x), with C(x) recovered from sum_a P = 1\n                    al = a.alpha\n                    C = (al + 1 - (Ste / lam).sum(1, keepdims=True)) / (1.0 / lam).sum()\n                    Pq = (Ste + C) / ((al + 1) * lam)\n                    rec["prior_corrected"] = full_metrics(yte, np.argmax(Pq, 1))\n                if head in ("val", "bandit") and weight == "plain":\n                    # population minimiser under MSE: Q_a = (alpha+1) P(a|x) - 1 for the plain\n                    # reward, so argmax_a lambda_a (Q_a + 1) is the decision RB would make\n                    yr = np.argmax(lam * (Ste + 1.0), 1)\n                    rec["lambda_rescaled"] = full_metrics(yte, yr)\n                    if a.save_preds:\n                        np.save(f"{a.save_preds}/{a.dataset}_{method}_{a.loss}{a.tag}_s{seed}_rescaled.npy",\n                                yr.astype(np.int8))\n                if a.save_preds:\n                    np.save(f"{a.save_preds}/{a.dataset}_{method}_{a.loss}{a.tag}_s{seed}.npy", yp.astype(np.int8))\n                    if "prior_corrected" in rec:\n                        np.save(f"{a.save_preds}/{a.dataset}_{method}_{a.loss}{a.tag}_s{seed}_priorcorr.npy",\n                                np.argmax(Pq, 1).astype(np.int8))\n\n            rec["seconds"] = round(time.time() - t0, 1)\n            results.append(rec)\n            msg = (f"  => {method} seed={seed}: supMacro {rec[\'supported_macro_recall\']:.4f} "\n                   f"macroF1 {rec[\'macro_f1_supported\']:.4f} FPR {rec[\'false_positive_rate\']:.4f} "\n                   f"macroAUPRC {rec[\'threshold_free\'][\'macro_auprc\']:.4f}")\n            if "recalibrated" in rec:\n                msg += f" | recal macroF1 {rec[\'recalibrated\'][\'macro_f1_supported\']:.4f}"\n            print(msg, flush=True)\n            with open(a.out, "w") as f:\n                json.dump(results, f, indent=1)\n    print(f"\\nwrote {len(results)} runs to {a.out}")\n\n\nif __name__ == "__main__":\n    main()\n'
REV_ANALYSE = '"""\nrev_analyse.py -- statistics for the revision experiments (nf_revision.py output).\n\nFor every 2x2 (head x sampler) found in the file it reports, per metric:\n  sampler effect, reward/weight effect, weight added to sampler, interaction,\n  each with paired-t 95% CI and the exact two-sided sign-flip randomisation p.\nMetrics: argmax operating point, threshold-free, and validation-recalibrated.\nAlso: unique flows seen per class, and (with --preds) the agreement between\nlambda-rescaled plain-reward predictions and the frequency-reward model (R2 test).\n\nUsage:  python src/rev_analyse.py results/rev_nf_unsw_mse.json [--preds results/preds]\n"""\nimport argparse\nimport glob\nimport itertools\nimport json\nimport os\n\nimport numpy as np\nfrom scipy import stats\n\nFAM = ["Normal", "DoS", "Probe", "Access", "Malware", "Other"]\nMETRICS = [\n    ("supported_macro_recall", lambda r: r["supported_macro_recall"]),\n    ("macro_f1", lambda r: r["macro_f1_supported"]),\n    ("detection_f1", lambda r: r["detection_f1"]),\n    ("FPR", lambda r: r["false_positive_rate"]),\n    ("macro_AUPRC", lambda r: r["threshold_free"]["macro_auprc"]),\n    ("binary_AUPRC", lambda r: r["threshold_free"]["binary_auprc"]),\n    ("binary_AUROC", lambda r: r["threshold_free"]["binary_auroc"]),\n    ("recal_macro_recall", lambda r: r["recalibrated"]["supported_macro_recall"]),\n    ("recal_macro_f1", lambda r: r["recalibrated"]["macro_f1_supported"]),\n    ("recal_FPR", lambda r: r["recalibrated"]["false_positive_rate"]),\n    ("recall@FPR=1e-3", lambda r: r["threshold_free"]["recall_at_fpr_0.001"]),\n    ("recall@FPR=1e-2", lambda r: r["threshold_free"]["recall_at_fpr_0.01"]),\n]\n\n\ndef signflip_p(d):\n    """Exact two-sided sign-flip randomisation test on paired differences."""\n    d = np.asarray(d, float); n = len(d)\n    obs = abs(d.mean())\n    if n > 20:                                   # Monte Carlo beyond 2^20\n        rs = np.random.RandomState(0)\n        s = rs.choice([-1, 1], size=(200000, n))\n        return float((np.abs((s * d).mean(1)) >= obs - 1e-12).mean())\n    tot = 0; hit = 0\n    for signs in itertools.product([-1, 1], repeat=n):\n        tot += 1; hit += abs((np.array(signs) * d).mean()) >= obs - 1e-12\n    return hit / tot\n\n\ndef line(label, d):\n    d = np.asarray(d, float); n = len(d); m = d.mean()\n    if n < 2:\n        print(f"    {label:34s} {m:+.4f}  (n={n})"); return\n    se = d.std(ddof=1) / np.sqrt(n); tc = stats.t.ppf(0.975, n - 1)\n    p = stats.ttest_1samp(d, 0).pvalue\n    print(f"    {label:34s} {m:+.4f}  CI [{m-tc*se:+.4f}, {m+tc*se:+.4f}]  "\n          f"p_t={p:.4g}  p_exact={signflip_p(d):.4g}  +{int((d>0).sum())}/{n}")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("files", nargs="+")\n    ap.add_argument("--preds", default=None)\n    ap.add_argument("--processed", default=None, help="folder with <dataset>_test.y.npy (bootstrap)")\n    ap.add_argument("--boot", type=int, default=1000)\n    ap.add_argument("--overlap", nargs=2, default=None, metavar=("PREFIX_A", "PREFIX_B"),\n                    help="report source-row overlap between two prepared datasets")\n    a = ap.parse_args()\n\n    if a.overlap:\n        ra = np.concatenate([np.load(f"{a.overlap[0]}_{sp}.rows.npy") for sp in ("train", "test")])\n        rb = np.concatenate([np.load(f"{a.overlap[1]}_{sp}.rows.npy") for sp in ("train", "test")])\n        inter = np.intersect1d(ra, rb).size\n        print(f"source-row overlap: {inter} rows = {100*inter/len(rb):.1f}% of {a.overlap[1]} "\n              f"({len(rb)}) and {100*inter/len(ra):.1f}% of {a.overlap[0]} ({len(ra)})")\n\n    for path in a.files:\n        recs = json.load(open(path))\n        print(f"\\n==================== {os.path.basename(path)} ====================")\n        by = {}\n        for r in recs:\n            by.setdefault(r["method"], {})[r["seed"]] = r\n        ds = recs[0]["dataset"]; loss = recs[0].get("loss")\n\n        for head in ("val", "ce", "bandit"):\n            for samp in ("frozen", "epoch", "iw"):\n                names = {k: f"{head}-{w}-{s}" for k, w, s in\n                         [("PU", "plain", "none"), ("RU", "freq", "none"),\n                          ("PB", "plain", samp), ("RB", "freq", samp)]}\n                if not all(n in by for n in names.values()):\n                    continue\n                seeds = sorted(set.intersection(*[set(by[n]) for n in names.values()]))\n                print(f"\\n--- {head} head, balanced = {samp}  (n={len(seeds)} paired seeds) ---")\n                for mname, get in METRICS:\n                    try:\n                        V = {k: np.array([get(by[n][s]) for s in seeds]) for k, n in names.items()}\n                    except (KeyError, TypeError):\n                        continue\n                    print(f"  {mname}:  PU {V[\'PU\'].mean():.4f}  RU {V[\'RU\'].mean():.4f}  "\n                          f"PB {V[\'PB\'].mean():.4f}  RB {V[\'RB\'].mean():.4f}")\n                    line("sampler alone (PB-PU)", V["PB"] - V["PU"])\n                    line("weight alone (RU-PU)", V["RU"] - V["PU"])\n                    line("weight on sampler (RB-PB)", V["RB"] - V["PB"])\n                    line("interaction", (V["RB"] - V["PB"]) - (V["RU"] - V["PU"]))\n\n        # unique flows seen\n        print("\\n--- unique training flows seen per class (mean over seeds) ---")\n        print("    " + " ".join(f"{f:>9s}" for f in FAM))\n        for m, d in sorted(by.items()):\n            u = [r.get("unique_seen_per_class") for r in d.values()]\n            if u and u[0]:\n                tot = np.mean([r["train_per_class"] for r in d.values()], 0)\n                um = np.mean(u, 0)\n                print(f"  {m:18s} " + " ".join(f"{x:9.0f}" for x in um) +\n                      "   (% of class: " + " ".join(f"{100*x/t:.0f}" for x, t in zip(um, tot)) + ")")\n\n        # baselines\n        for m in ("ce-plain-none", "extra_trees", "rf", "xgboost"):\n            if m in by:\n                v = [r["supported_macro_recall"] for r in by[m].values()]\n                f = [r["macro_f1_supported"] for r in by[m].values()]\n                extra = ""\n                la = [r["logit_adjusted"]["supported_macro_recall"] for r in by[m].values() if "logit_adjusted" in r]\n                if la:\n                    extra = f"  | logit-adjusted supMacro {np.mean(la):.4f}"\n                print(f"  {m:14s} supMacro {np.mean(v):.4f}  macroF1 {np.mean(f):.4f}{extra}")\n\n        # prior-corrected frequency-reward models (reviewer Mo3)\n        for m in sorted(by):\n            pcs = [r["prior_corrected"] for r in by[m].values() if "prior_corrected" in r]\n            if pcs:\n                base = [r for r in by[m].values() if "prior_corrected" in r]\n                print(f"  prior-corrected {m:20s} supMacro {np.mean([b[\'supported_macro_recall\'] for b in base]):.4f}"\n                      f" -> {np.mean([p[\'supported_macro_recall\'] for p in pcs]):.4f} | macroF1 "\n                      f"{np.mean([b[\'macro_f1_supported\'] for b in base]):.4f} -> "\n                      f"{np.mean([p[\'macro_f1_supported\'] for p in pcs]):.4f} | FPR "\n                      f"{np.mean([b[\'false_positive_rate\'] for b in base]):.4f} -> "\n                      f"{np.mean([p[\'false_positive_rate\'] for p in pcs]):.4f}")\n\n        # test-set bootstrap over the 2x2 contrasts (reviewer M5)\n        if a.preds and a.processed:\n            yte = np.load(f"{a.processed}/{ds}_test.y.npy")\n            for head in ("val", "ce", "bandit"):\n                for samp in ("frozen", "epoch", "iw"):\n                    names = {"PU": f"{head}-plain-none", "RU": f"{head}-freq-none",\n                             "PB": f"{head}-plain-{samp}", "RB": f"{head}-freq-{samp}"}\n                    P = {}\n                    for k, n in names.items():\n                        fs = sorted(glob.glob(f"{a.preds}/{ds}_{n}_{loss}_s*.npy"))\n                        fs = [f for f in fs if not f.endswith(("_rescaled.npy", "_priorcorr.npy"))]\n                        P[k] = {f.split("_s")[-1][:-4]: np.load(f) for f in fs}\n                    seeds = sorted(set.intersection(*[set(v) for v in P.values()])) if all(P.values()) else []\n                    if len(seeds) < 2:\n                        continue\n                    print(f"\\n--- test-set bootstrap (B={a.boot}), {head} head, balanced={samp}, n_seeds={len(seeds)} ---")\n                    rs = np.random.RandomState(0)\n                    def mrec(y, p, w):\n                        cm = np.bincount(y * 6 + p, weights=w, minlength=36).reshape(6, 6)\n                        sup = cm.sum(1) > 0\n                        return float(np.mean(np.diag(cm)[sup] / cm.sum(1)[sup]))\n                    out = {"sampler": [], "weight": [], "weight_on_sampler": [], "interaction": []}\n                    for _ in range(a.boot):\n                        w = rs.poisson(1.0, len(yte)).astype(float)\n                        v = {k: np.mean([mrec(yte, P[k][s].astype(int), w) for s in seeds]) for k in P}\n                        out["sampler"].append(v["PB"] - v["PU"]); out["weight"].append(v["RU"] - v["PU"])\n                        out["weight_on_sampler"].append(v["RB"] - v["PB"])\n                        out["interaction"].append((v["RB"] - v["PB"]) - (v["RU"] - v["PU"]))\n                    for k, d in out.items():\n                        d = np.array(d)\n                        print(f"    supported macro recall, {k:18s} mean {d.mean():+.4f}  "\n                              f"95% bootstrap CI [{np.percentile(d, 2.5):+.4f}, {np.percentile(d, 97.5):+.4f}]")\n\n        # R2 mechanism test: lambda-rescaled plain vs freq predictions\n        if a.preds:\n            print("\\n--- lambda-rescaling test (agreement with frequency-reward model) ---")\n            for samp in ("none", "frozen", "epoch"):\n                ag, base = [], []\n                for f in glob.glob(f"{a.preds}/{ds}_val-plain-{samp}_{loss}_s*_rescaled.npy"):\n                    s = f.split("_s")[-1].split("_")[0]\n                    g = f"{a.preds}/{ds}_val-freq-{samp}_{loss}_s{s}.npy"\n                    p0 = f"{a.preds}/{ds}_val-plain-{samp}_{loss}_s{s}.npy"\n                    if os.path.exists(g) and os.path.exists(p0):\n                        R, Fq, P0 = np.load(f), np.load(g), np.load(p0)\n                        ag.append((R == Fq).mean()); base.append((P0 == Fq).mean())\n                if ag:\n                    print(f"  sampler={samp:6s} rescaled-plain vs freq: {np.mean(ag):.4f}   "\n                          f"(unrescaled plain vs freq: {np.mean(base):.4f}, n={len(ag)})")\n\n\nif __name__ == "__main__":\n    main()\n'
PREPARE_NF = '"""\nprepare_nf.py -- preprocessing for the standardised NetFlow (NF-v2) datasets.\n\nWHY THIS EXISTS\nThe original pipeline projected three heterogeneous benchmarks onto a\nhand-built 10-feature schema.  Two problems followed: features had to be\nzero-filled where a dataset lacked them, and a mapping mistake (UNSW \'rate\'\nis a packet rate, \'synack\' is a timing interval) aligned semantically\ndifferent columns across datasets.  Both manufacture domain shift, which is\nfatal for a cross-dataset study.\n\nThe NF-v2 datasets of Sarhan, Layeghy & Portmann ("Towards a Standard\nFeature Set for NIDS Datasets", Mobile Networks and Applications, 2022)\nsolve this at the source: NF-UNSW-NB15-v2, NF-ToN-IoT-v2, NF-BoT-IoT-v2 and\nNF-CSE-CIC-IDS2018-v2 all share the SAME 43 extended NetFlow features.\nNo projection, no zero-fill, no mapping to invent.\n\nLEAKAGE GUARD\nSarhan et al. drop the TTL-based features (sttl, dttl, ct_state_ttl,\nMIN_TTL, MAX_TTL) because of their extreme correlation with the labels, and\ndrop flow identifiers (IPs, ports, timestamps) to stop the model keying on\nattacker/victim endpoints.  We do the same, by default and explicitly.\nReported accuracies that keep these features are not comparable to ours.\n\nUsage\n    python prepare_nf.py --input NF-UNSW-NB15-v2.csv --dataset nf_unsw \\\n        --out data/processed/nf_unsw --cap 400000 --seed 42\n"""\nimport argparse\nimport json\nimport os\n\nimport numpy as np\nimport pandas as pd\n\n# --------------------------------------------------------------------------\n# Coarse six-family taxonomy, shared across every NF dataset.\n# Keys are lower-cased NF \'Attack\' values with spaces/hyphens stripped.\n# --------------------------------------------------------------------------\nCANONICAL_LABELS = ["Normal", "DoS", "Probe", "Access", "Malware", "Other"]\n\nNF_LABEL_MAP = {\n    "benign": "Normal",\n\n    "dos": "DoS",\n    "ddos": "DoS",\n\n    "reconnaissance": "Probe",\n    "scanning": "Probe",\n    "analysis": "Probe",\n\n    "exploits": "Access",\n    "backdoor": "Access",\n    "injection": "Access",\n    "password": "Access",\n    "bruteforce": "Access",\n    "bruteforce web": "Access",\n    "xss": "Access",\n    "mitm": "Access",\n    "webattacks": "Access",\n    "infilteration": "Access",\n    "infiltration": "Access",\n\n    "bot": "Malware",\n    "worms": "Malware",\n    "ransomware": "Malware",\n    "shellcode": "Malware",\n    "theft": "Malware",\n\n    "fuzzers": "Other",\n    "generic": "Other",\n}\n\n# Flow identifiers: keying on these learns the testbed, not the attack.\nID_COLS = [\n    "IPV4_SRC_ADDR", "IPV4_DST_ADDR", "L4_SRC_PORT", "L4_DST_PORT",\n    "FLOW_START_MILLISECONDS", "FLOW_END_MILLISECONDS",\n    "Dataset", "dataset",\n]\n# Label columns (never features).\nLABEL_COLS = ["Label", "Attack", "label", "attack"]\n# Label-leaking features per Sarhan et al.\nLEAKY_COLS = ["MIN_TTL", "MAX_TTL", "sttl", "dttl", "ct_state_ttl", "TTL"]\n\n\ndef _norm(s):\n    return str(s).strip().lower().replace("-", "").replace("_", "").replace("  ", " ")\n\n\ndef map_labels(attack_series):\n    out, unmapped = [], {}\n    for raw in attack_series.astype(str):\n        key = _norm(raw)\n        fam = NF_LABEL_MAP.get(key)\n        if fam is None:\n            # tolerate variants such as \'DoS attacks-Hulk\'\n            for k, v in NF_LABEL_MAP.items():\n                if key.startswith(k):\n                    fam = v\n                    break\n        if fam is None:\n            fam = "Other"\n            unmapped[raw] = unmapped.get(raw, 0) + 1\n        out.append(CANONICAL_LABELS.index(fam))\n    return np.asarray(out, dtype=np.int64), unmapped\n\n\ndef stratified_subsample(df, label_col, cap, floor, seed):\n    """Cap total rows while never dropping a class below `floor` (or its full\n    size if smaller).  This is subsampling only -- no oversampling, so no\n    duplicate can leak across the later split."""\n    if cap is None or len(df) <= cap:\n        return df\n    rng = np.random.RandomState(seed)\n    groups = {k: g for k, g in df.groupby(label_col)}\n    kept, reserved = [], 0\n    for k, g in groups.items():\n        take = min(floor, len(g))\n        kept.append(g.sample(n=take, random_state=rng.randint(1 << 31)))\n        reserved += take\n    budget = max(cap - reserved, 0)\n    left = {k: len(g) - min(floor, len(g)) for k, g in groups.items()}\n    tot = sum(left.values())\n    if budget > 0 and tot > 0:\n        for i, (k, g) in enumerate(groups.items()):\n            if left[k] <= 0:\n                continue\n            extra = min(int(round(budget * left[k] / tot)), left[k])\n            if extra > 0:\n                pool = g.drop(index=kept[i].index)\n                kept.append(pool.sample(n=extra, random_state=rng.randint(1 << 31)))\n    return pd.concat(kept).sample(frac=1.0, random_state=seed).reset_index(drop=True)\n\n\ndef count_classes(path, chunksize):\n    """Pass 1: read ONLY the label column to get exact class counts cheaply."""\n    attack_col = None\n    counts, total = {}, 0\n    head = pd.read_csv(path, nrows=1)\n    head.columns = [c.strip() for c in head.columns]\n    attack_col = next((c for c in ("Attack", "attack") if c in head.columns), None)\n    if attack_col is None:\n        raise KeyError(f"No \'Attack\' column. Found: {list(head.columns)[:12]}")\n    for chunk in pd.read_csv(path, usecols=[attack_col], chunksize=chunksize):\n        chunk.columns = [c.strip() for c in chunk.columns]\n        fam, _ = map_labels(chunk[attack_col])\n        for f, n in zip(*np.unique(fam, return_counts=True)):\n            counts[int(f)] = counts.get(int(f), 0) + int(n)\n        total += len(chunk)\n    return counts, total, attack_col\n\n\ndef plan_quota(counts, cap, floor):\n    """How many rows to keep per class.\n\n    Preserves the NATURAL class imbalance (the phenomenon under study) while\n    guaranteeing a floor for rare families.  A flat per-class cap would\n    flatten an 88%-benign corpus into a near-balanced one and silently\n    destroy the imbalance the paper is about.\n    """\n    if cap is None:\n        return {c: n for c, n in counts.items()}\n    quota = {c: min(floor, n) for c, n in counts.items()}\n    reserved = sum(quota.values())\n    budget = max(cap - reserved, 0)\n    left = {c: counts[c] - quota[c] for c in counts}\n    tot = sum(left.values())\n    if budget > 0 and tot > 0:\n        for c in counts:\n            quota[c] += min(int(round(budget * left[c] / tot)), left[c])\n    return quota\n\n\nPLAN = {}\n\n\ndef read_and_subsample(path, cap, floor, seed, chunksize=1_000_000):\n    """Memory-safe two-pass read.\n\n    NF-CSE-CIC-IDS2018-v2 has ~18.9M rows and NF-ToN-IoT-v2 ~16.9M; a plain\n    read_csv of either exhausts Colab\'s ~12 GB.\n\n    Pass 1 counts classes from the label column alone.  Pass 2 streams the\n    full rows and keeps each class at its planned quota, sampling each chunk\n    at the per-class acceptance rate so the retained sample is an unbiased\n    draw that PRESERVES the original imbalance.  Peak memory is one chunk\n    plus the retained sample.\n    """\n    rng = np.random.RandomState(seed)\n    print("  pass 1/2: counting classes ...", flush=True)\n    counts, total, attack_col = count_classes(path, chunksize)\n    named = {CANONICAL_LABELS[c]: n for c, n in sorted(counts.items())}\n    print(f"    {total:,} rows, classes: {named}")\n\n    quota = plan_quota(counts, cap, floor)\n    PLAN.update({"corpus_counts": {CANONICAL_LABELS[c]: int(n) for c, n in sorted(counts.items())},\n                 "planned_quota": {CANONICAL_LABELS[c]: int(quota[c]) for c in sorted(quota)},\n                 "quota_rule": "quota_c = min(floor, n_c) + round((cap - sum_j min(floor, n_j)) * "\n                               "(n_c - min(floor, n_c)) / sum_j (n_j - min(floor, n_j)))"})\n    rates = {c: (quota[c] / counts[c] if counts[c] else 0.0) for c in counts}\n    print(f"    quota: { {CANONICAL_LABELS[c]: quota[c] for c in sorted(quota)} }")\n\n    kept = {c: [] for c in counts}\n    got = {c: 0 for c in counts}\n    seen_rows = 0\n    print("  pass 2/2: streaming rows ...", flush=True)\n    for chunk in pd.read_csv(path, low_memory=False, chunksize=chunksize):\n        chunk.columns = [c.strip() for c in chunk.columns]\n        fam, _ = map_labels(chunk[attack_col])\n        chunk = chunk.assign(_family=fam, _row=np.arange(seen_rows, seen_rows + len(chunk)))\n        seen_rows += len(chunk)\n        for c, grp in chunk.groupby("_family"):\n            need = quota[c] - got[c]\n            if need <= 0:\n                continue\n            # accept at the class rate, but never exceed the remaining need\n            n_take = min(need, rng.binomial(len(grp), min(1.0, rates[c])))\n            if n_take <= 0 and need > 0 and len(grp) and rates[c] >= 1.0:\n                n_take = min(need, len(grp))\n            if n_take > 0:\n                kept[c].append(grp.sample(n=int(n_take),\n                                          random_state=rng.randint(1 << 31)))\n                got[c] += int(n_take)\n        print(f"    {seen_rows:,}/{total:,} rows", flush=True)\n\n    df = pd.concat([pd.concat(v) for v in kept.values() if v], ignore_index=True)\n    df = df.sample(frac=1.0, random_state=seed).reset_index(drop=True)\n    print(f"  retained {len(df):,} rows, imbalance preserved: "\n          f"{ {CANONICAL_LABELS[c]: got[c] for c in sorted(got) if got[c]} }")\n    return df, total\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--input", required=True)\n    ap.add_argument("--dataset", required=True, help="short name, e.g. nf_unsw")\n    ap.add_argument("--out", required=True, help="output prefix")\n    ap.add_argument("--cap", type=int, default=400000, help="0 = keep all rows")\n    ap.add_argument("--floor", type=int, default=1000)\n    ap.add_argument("--test-frac", type=float, default=0.30)\n    ap.add_argument("--seed", type=int, default=42)\n    ap.add_argument("--keep-ttl", action="store_true",\n                    help="keep TTL features (NOT recommended: they leak the label)")\n    ap.add_argument("--stream", action="store_true",\n                    help="chunked read + reservoir sampling; use for files "\n                         "over ~5M rows (NF-ToN-IoT-v2, NF-CSE-CIC-IDS2018-v2)")\n    ap.add_argument("--chunksize", type=int, default=1_000_000)\n    a = ap.parse_args()\n\n    os.makedirs(os.path.dirname(a.out) or ".", exist_ok=True)\n    cap = None if a.cap == 0 else a.cap\n\n    if a.stream:\n        print(f"streaming {a.input} (chunksize={a.chunksize:,}) ...")\n        df, total_rows = read_and_subsample(a.input, cap, a.floor, a.seed, a.chunksize)\n        print(f"  {len(df)} rows x {len(df.columns)} columns retained")\n        unmapped = {}\n    else:\n        print(f"reading {a.input} ...")\n        df = pd.read_csv(a.input, low_memory=False)\n        df.columns = [c.strip() for c in df.columns]\n        total_rows = len(df)\n        print(f"  {len(df)} rows x {len(df.columns)} columns")\n        attack_col = next((c for c in ("Attack", "attack") if c in df.columns), None)\n        if attack_col is None:\n            raise KeyError(f"No \'Attack\' column. Found: {list(df.columns)[:12]}")\n        y0, unmapped = map_labels(df[attack_col])\n        df["_family"] = y0\n        df["_row"] = np.arange(len(df))\n        df = stratified_subsample(df, "_family", cap, a.floor, a.seed)\n\n    if unmapped:\n        print("  WARNING unmapped attack labels -> \'Other\':", unmapped)\n\n    drop = set(ID_COLS) | set(LABEL_COLS)\n    if not a.keep_ttl:\n        drop |= set(LEAKY_COLS)\n    feat_cols = [c for c in df.columns\n                 if c not in drop and c not in ("_family", "_row")\n                 and pd.api.types.is_numeric_dtype(df[c])]\n    dropped_present = sorted((drop & set(df.columns)))\n    print(f"  dropped ({len(dropped_present)}): {dropped_present}")\n    print(f"  using {len(feat_cols)} numeric NetFlow features")\n\n    X = df[feat_cols].replace([np.inf, -np.inf], np.nan).fillna(0.0)\n    X = X.values.astype(np.float32)\n    y = df["_family"].values.astype(np.int64)\n    rows = df["_row"].values.astype(np.int64)\n\n    # stratified split (subsample-only above, so no duplicate can cross the split)\n    rng = np.random.RandomState(a.seed)\n    tr_idx, te_idx = [], []\n    for c in np.unique(y):\n        idx = np.where(y == c)[0]\n        rng.shuffle(idx)\n        n_te = max(1, int(round(len(idx) * a.test_frac))) if len(idx) > 1 else 0\n        te_idx.extend(idx[:n_te])\n        tr_idx.extend(idx[n_te:])\n    tr_idx, te_idx = np.array(tr_idx), np.array(te_idx)\n\n    for split, idx in (("train", tr_idx), ("test", te_idx)):\n        np.save(f"{a.out}_{split}.X.npy", X[idx])\n        np.save(f"{a.out}_{split}.y.npy", y[idx])\n        np.save(f"{a.out}_{split}.rows.npy", rows[idx])   # source-row ids (overlap audit)\n        counts = {CANONICAL_LABELS[i]: int(n)\n                  for i, n in enumerate(np.bincount(y[idx], minlength=6))}\n        meta = {"dataset": a.dataset, "split": split,\n                "n_samples": int(len(idx)), "n_features": int(X.shape[1]),\n                "features": feat_cols, "dropped_columns": dropped_present,\n                "ttl_features_dropped": not a.keep_ttl,\n                "label_order": CANONICAL_LABELS, "class_counts": counts,\n                "cap": a.cap, "floor": a.floor, "seed": a.seed,\n                "source_total_rows": int(total_rows), "streamed": bool(a.stream),\n                "zero_filled_features": [], **PLAN}   # NF-v2 shares all features: none\n        with open(f"{a.out}_{split}.meta.json", "w") as f:\n            json.dump(meta, f, indent=2)\n        print(f"  [{split}] {len(idx)} rows -> {counts}")\n\n    print(f"\\nsupported families: "\n          f"{[CANONICAL_LABELS[i] for i, n in enumerate(np.bincount(y, minlength=6)) if n > 0]}")\n\n\nif __name__ == "__main__":\n    main()\n'
MAKE_TABLES = '"""\nmake_revision_tables.py -- turn the revision result files into LaTeX.\n\nReads results/rev_*.json (written by nf_revision.py) and, when available, the saved\ntest predictions and test labels, and writes into --out:\n\n  revnums.tex          \\\\RV{<spec>}{<quantity>} values used in the running text\n  tab_robust.tex       the factorial contrasts under every specification\n  tab_thrfree.tex      threshold-free, recalibrated and prior-corrected metrics\n  tab_baselines.tex    tuned supervised and tree baselines\n  tab_unique.tex       unique training flows per class under each sampler, and run time\n\nMissing results render as a red placeholder, so the manuscript always compiles.\n\nUsage:  python src/make_revision_tables.py --results results --out manuscript/gen \\\\\n            [--preds results/preds --processed data/processed]\n"""\nimport argparse\nimport glob\nimport itertools\nimport json\nimport os\n\nimport numpy as np\nfrom scipy import stats\n\nFAM = ["Normal", "DoS", "Probe", "Access", "Malware", "Other"]\nTBD = r"\\TBD{}"\n\n# specification key -> (file, head, balanced-sampler level, label, dataset)\nSPECS = [\n    ("huber1-frozen", "rev_nf_unsw_huber1.json", "val", "frozen", r"Huber $\\kappa{=}1$, frozen bootstrap (original)"),\n    ("huber1-epoch", "rev_nf_unsw_huber1.json", "val", "epoch", r"Huber $\\kappa{=}1$, per-epoch redraw"),\n    ("mse-frozen", "rev_nf_unsw_mse.json", "val", "frozen", r"Squared loss, frozen bootstrap"),\n    ("mse-epoch", "rev_nf_unsw_mse.json", "val", "epoch", r"Squared loss, per-epoch redraw"),\n    ("mse-iw", "rev_nf_unsw_mse.json", "val", "iw", r"Squared loss, importance weights"),\n    ("ce-frozen", "rev_nf_unsw_ce.json", "ce", "frozen", r"Weighted cross-entropy, frozen bootstrap"),\n    ("ce-epoch", "rev_nf_unsw_ce.json", "ce", "epoch", r"Weighted cross-entropy, per-epoch redraw"),\n    ("ce-iw", "rev_nf_unsw_ce.json", "ce", "iw", r"Weighted cross-entropy, importance weights"),\n    ("bandit-frozen", "rev_nf_unsw_bandit.json", "bandit", "frozen", r"$\\varepsilon$-greedy bandit + replay, frozen"),\n    ("bandit-epoch", "rev_nf_unsw_bandit.json", "bandit", "epoch", r"$\\varepsilon$-greedy bandit + replay, per-epoch"),\n] + [\n    (f"alpha{a}", f"rev_sweep_alpha{a}.json", "val", "epoch", rf"Squared loss, $\\alpha={a}$ (fixed grid)")\n    for a in ("1", "2", "5", "10")\n] + [\n    (f"kappa{k}", f"rev_sweep_kappa{k}.json", "val", "epoch",\n     (r"Huber, $\\kappa=(\\alpha{+}1)\\lambda_{\\max}$" if k == "auto" else rf"Huber, $\\kappa={k}$") + " (fixed grid)")\n    for k in ("0.5", "1", "2", "5", "10", "auto")\n] + [\n    ("ton-frozen", "rev_nf_ton_mse.json", "val", "frozen", r"NF-ToN-IoT-v2, squared loss, frozen"),\n    ("ton-epoch", "rev_nf_ton_mse.json", "val", "epoch", r"NF-ToN-IoT-v2, squared loss, per-epoch"),\n    ("bot-frozen", "rev_nf_bot_mse.json", "val", "frozen", r"NF-BoT-IoT-v2, squared loss, frozen"),\n    ("bot-epoch", "rev_nf_bot_mse.json", "val", "epoch", r"NF-BoT-IoT-v2, squared loss, per-epoch"),\n    ("small2-frozen", "rev_nf_unsw_small2_mse.json", "val", "frozen", r"100\\,k draw, distinct seed, frozen"),\n    ("small2-epoch", "rev_nf_unsw_small2_mse.json", "val", "epoch", r"100\\,k draw, distinct seed, per-epoch"),\n    ("trueprior-frozen", "rev_nf_unsw_trueprior_mse.json", "val", "frozen", r"True corpus prior, frozen"),\n    ("trueprior-epoch", "rev_nf_unsw_trueprior_mse.json", "val", "epoch", r"True corpus prior, per-epoch"),\n    ("widegrid", "rev_nf_unsw_widegrid.json", "val", "epoch", r"Wider grid, squared loss, per-epoch (PB, RB only)"),\n    ("widegrid-frozen", "rev_nf_unsw_widegrid.json", "val", "frozen", r"Wider grid, squared loss, frozen (PB, RB only)"),\n]\nGROUPS = [  # (heading, spec keys) for the robustness table\n    ("Loss and clipping (NF-UNSW-NB15-v2, 10 seeds)", ["huber1-frozen", "huber1-epoch", "mse-frozen", "mse-epoch", "mse-iw"]),\n    ("Supervised control (10 seeds)", ["ce-frozen", "ce-epoch", "ce-iw"]),\n    ("Exploration-based agent (10 seeds)", ["bandit-frozen", "bandit-epoch"]),\n    (r"Reward multiplier $\\alpha$ and Huber threshold $\\kappa$ (5 seeds)",\n     [f"alpha{a}" for a in ("1", "2", "5", "10")] + [f"kappa{k}" for k in ("0.5", "1", "2", "5", "10", "auto")]),\n    ("Further corpora and draws (10 seeds; true prior 5 seeds)",\n     ["ton-frozen", "ton-epoch", "bot-frozen", "bot-epoch", "small2-frozen", "small2-epoch",\n      "trueprior-frozen", "trueprior-epoch"]),\n    ("Wider hyperparameter grid (5 seeds)", ["widegrid-frozen", "widegrid"]),\n]\n\n\ndef fnum(x, d=3, sign=True):\n    if x is None or (isinstance(x, float) and not np.isfinite(x)):\n        return TBD\n    s = f"{x:+.{d}f}" if sign else f"{x:.{d}f}"\n    return s.replace("-", "$-$") if s.startswith("-") else s\n\n\ndef fp(p):\n    if p is None or not np.isfinite(p):\n        return TBD\n    return r"$<10^{-4}$" if p < 1e-4 else (f"{p:.4f}" if p < 0.01 else f"{p:.3f}")\n\n\ndef signflip(d):\n    d = np.asarray(d, float); n = len(d); obs = abs(d.mean())\n    if n > 16:\n        rs = np.random.RandomState(0); s = rs.choice([-1, 1], size=(200000, n))\n        return float((np.abs((s * d).mean(1)) >= obs - 1e-12).mean())\n    hits = sum(abs((np.array(sg) * d).mean()) >= obs - 1e-12 for sg in itertools.product([-1, 1], repeat=n))\n    return hits / 2 ** n\n\n\ndef ci(d):\n    d = np.asarray(d, float); n = len(d)\n    if n < 2:\n        return (np.nan, np.nan, np.nan)\n    m = d.mean(); se = d.std(ddof=1) / np.sqrt(n); tc = stats.t.ppf(0.975, n - 1)\n    return m, m - tc * se, m + tc * se\n\n\ndef get(rec, path):\n    cur = rec\n    for k in path.split("."):\n        if cur is None or k not in cur:\n            return None\n        cur = cur[k]\n    return cur\n\n\nclass Results:\n    def __init__(self, res_dir):\n        self.files = {}\n        for f in glob.glob(os.path.join(res_dir, "rev_*.json")):\n            by = {}\n            for r in json.load(open(f)):\n                by.setdefault(r["method"], {})[r["seed"]] = r\n            self.files[os.path.basename(f)] = by\n\n    def cells(self, fname, head, samp):\n        by = self.files.get(fname)\n        if not by:\n            return None, []\n        names = {"PU": f"{head}-plain-none", "RU": f"{head}-freq-none",\n                 "PB": f"{head}-plain-{samp}", "RB": f"{head}-freq-{samp}"}\n        avail = {k: by.get(n, {}) for k, n in names.items()}\n        return avail, names\n\n\ndef contrasts(avail, path="supported_macro_recall"):\n    out = {}\n    full = [k for k in ("PU", "RU", "PB", "RB") if avail.get(k)]\n    if {"PB", "RB"} <= set(full):\n        seeds = sorted(set(avail["PB"]) & set(avail["RB"]))\n        out["n_pbrb"] = len(seeds)\n        d = [get(avail["RB"][s], path) - get(avail["PB"][s], path) for s in seeds]\n        out["rbpb"] = ci(d); out["rbpb_pe"] = signflip(d) if len(d) > 1 else np.nan\n        out["rbpb_t"] = stats.ttest_1samp(d, 0).pvalue if len(d) > 1 else np.nan\n    if len(full) == 4:\n        seeds = sorted(set.intersection(*[set(avail[k]) for k in full]))\n        out["n"] = len(seeds)\n        v = {k: np.array([get(avail[k][s], path) for s in seeds]) for k in full}\n        out["means"] = {k: float(v[k].mean()) for k in full}\n        out["sampler"] = ci(v["PB"] - v["PU"]); out["reward"] = ci(v["RU"] - v["PU"])\n        inter = (v["RB"] - v["PB"]) - (v["RU"] - v["PU"])\n        out["inter"] = ci(inter); out["inter_pe"] = signflip(inter)\n        out["inter_t"] = stats.ttest_1samp(inter, 0).pvalue\n        out["inter_pos"] = int((inter < 0).sum())\n    return out\n\n\ndef bootstrap_inter(preds, processed, ds, names, loss, B=1000, tag=""):\n    """Test-set Poisson bootstrap CI for the interaction on supported macro recall."""\n    yp = os.path.join(processed, f"{ds}_test.y.npy")\n    if not (preds and processed and os.path.exists(yp)):\n        return None\n    yte = np.load(yp)\n    P = {}\n    for k, n in names.items():\n        fs = [f for f in glob.glob(os.path.join(preds, f"{ds}_{n}_{loss}{tag}_s*.npy"))\n              if not f.endswith(("_rescaled.npy", "_priorcorr.npy"))]\n        P[k] = {os.path.basename(f).rsplit("_s", 1)[1][:-4]: np.load(f).astype(int) for f in fs}\n    if not all(P.values()):\n        return None\n    seeds = sorted(set.intersection(*[set(v) for v in P.values()]))\n    if len(seeds) < 2:\n        return None\n    rs = np.random.RandomState(0)\n\n    def mrec(y, p, w):\n        cm = np.bincount(y * 6 + p, weights=w, minlength=36).reshape(6, 6)\n        sup = cm.sum(1) > 0\n        return float(np.mean(np.diag(cm)[sup] / cm.sum(1)[sup]))\n    vals = []\n    for _ in range(B):\n        w = rs.poisson(1.0, len(yte)).astype(float)\n        m = {k: np.mean([mrec(yte, P[k][s], w) for s in seeds]) for k in P}\n        vals.append((m["RB"] - m["PB"]) - (m["RU"] - m["PU"]))\n    return float(np.percentile(vals, 2.5)), float(np.percentile(vals, 97.5))\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--results", required=True)\n    ap.add_argument("--out", required=True)\n    ap.add_argument("--preds", default=None)\n    ap.add_argument("--processed", default=None)\n    ap.add_argument("--boot", type=int, default=1000)\n    a = ap.parse_args()\n    os.makedirs(a.out, exist_ok=True)\n    R = Results(a.results)\n    nums = {}\n\n    def setnum(spec, key, val):\n        nums[f"{spec}@{key}"] = val\n\n    # ---------------- robustness table ----------------\n    rows = []\n    for heading, keys in GROUPS:\n        rows.append(rf"\\multicolumn{{8}}{{l}}{{\\emph{{{heading}}}}}\\\\")\n        for key in keys:\n            spec = next(s for s in SPECS if s[0] == key)\n            _, fname, head, samp, label = spec\n            avail, names = R.cells(fname, head, samp)\n            c = contrasts(avail) if avail else {}\n            f1 = contrasts(avail, "macro_f1_supported") if avail else {}\n            fpr = contrasts(avail, "false_positive_rate") if avail else {}\n            loss = "huber" if key.startswith(("huber", "kappa")) else "mse"\n            boot = None\n            if key in ("huber1-frozen", "mse-frozen", "mse-epoch", "mse-iw", "ce-epoch", "bandit-epoch") and avail:\n                ds = "nf_unsw"\n                boot = bootstrap_inter(a.preds, a.processed, ds, names, loss, a.boot)\n            n = c.get("n", c.get("n_pbrb"))\n            s_ = c.get("sampler", (None,) * 3); r_ = c.get("reward", (None,) * 3)\n            rb = c.get("rbpb", (None,) * 3); it = c.get("inter", (None,) * 3)\n            fpr_ratio = None\n            if fpr and "means" in fpr and fpr["means"].get("PB"):\n                fpr_ratio = fpr["means"]["RB"] / fpr["means"]["PB"]\n            cells = [\n                label,\n                str(n) if n else TBD,\n                fnum(s_[0]), fnum(r_[0]),\n                (fnum(rb[0]) + (rf" [{fnum(rb[1])},{fnum(rb[2])}]" if rb[0] is not None else "")),\n                (fnum(it[0]) + (rf" [{fnum(it[1])},{fnum(it[2])}]" if it[0] is not None else "")\n                 + (rf"$^{{b}}$[{fnum(boot[0])},{fnum(boot[1])}]" if boot else "")),\n                fp(c.get("inter_pe")) if "inter_pe" in c else TBD,\n                fnum(f1.get("rbpb", (None,))[0]) + " / " + (f"{fpr_ratio:.2f}" if fpr_ratio else TBD),\n            ]\n            rows.append(" & ".join(cells) + r" \\\\")\n            for k, v in (("sampler", s_[0]), ("reward", r_[0]), ("rbpb", rb[0]), ("inter", it[0]),\n                         ("interlo", it[1]), ("interhi", it[2]), ("rbpblo", rb[1]), ("rbpbhi", rb[2])):\n                setnum(key, k, fnum(v))\n            setnum(key, "pexact", fp(c.get("inter_pe")) if "inter_pe" in c else TBD)\n            setnum(key, "pt", fp(c.get("inter_t")) if "inter_t" in c else TBD)\n            setnum(key, "n", str(n) if n else TBD)\n            setnum(key, "neg", f"{c[\'inter_pos\']}/{c[\'n\']}" if "inter_pos" in c else TBD)\n            setnum(key, "f1rbpb", fnum(f1.get("rbpb", (None,))[0]))\n            setnum(key, "fprratio", f"{fpr_ratio:.2f}" if fpr_ratio else TBD)\n            if boot:\n                setnum(key, "bootlo", fnum(boot[0])); setnum(key, "boothi", fnum(boot[1]))\n            if "means" in c:\n                for k2, v2 in c["means"].items():\n                    setnum(key, f"mr{k2}", fnum(v2, 4, False))\n    with open(os.path.join(a.out, "tab_robust.tex"), "w") as f:\n        f.write("\\n".join(rows) + "\\n")\n\n    # ---------------- threshold-free / recalibrated / prior-corrected ----------------\n    rows = []\n    for key in ("huber1-frozen", "mse-frozen", "mse-epoch"):\n        spec = next(s for s in SPECS if s[0] == key)\n        _, fname, head, samp, label = spec\n        avail, names = R.cells(fname, head, samp)\n        rows.append(rf"\\multicolumn{{9}}{{l}}{{\\emph{{{label}}}}}\\\\")\n        for cond in ("PU", "RU", "PB", "RB"):\n            recs = list((avail or {}).get(cond, {}).values())\n\n            def m(path, d=3):\n                v = [get(r, path) for r in recs]\n                v = [x for x in v if x is not None]\n                return fnum(float(np.mean(v)), d, False) if v else TBD\n            pc = m("prior_corrected.macro_f1_supported") if cond in ("RU", "RB") else "--"\n            pcf = m("prior_corrected.false_positive_rate", 4) if cond in ("RU", "RB") else "--"\n            row = [cond, m("threshold_free.macro_auprc"), m("threshold_free.binary_auprc"),\n                   m("threshold_free.recall_at_fpr_0.001"), m("threshold_free.recall_at_fpr_0.01"),\n                   m("recalibrated.macro_f1_supported"), m("recalibrated.false_positive_rate", 4), pc, pcf]\n            rows.append(" & ".join(row) + r" \\\\")\n            for k, v in zip(("mauprc", "bauprc", "r1e3", "r1e2", "recalf1", "recalfpr", "pcf1", "pcfpr"), row[1:]):\n                setnum(f"{key}-{cond}", k, v)\n        # differences RB-PB on threshold-free metrics, paired\n        for path, k in (("threshold_free.macro_auprc", "dmauprc"), ("recalibrated.macro_f1_supported", "drecalf1"),\n                        ("threshold_free.binary_auprc", "dbauprc")):\n            if avail and avail.get("PB") and avail.get("RB"):\n                seeds = sorted(set(avail["PB"]) & set(avail["RB"]))\n                d = [get(avail["RB"][s], path) - get(avail["PB"][s], path) for s in seeds\n                     if get(avail["RB"][s], path) is not None]\n                if len(d) > 1:\n                    m_, lo, hi = ci(d)\n                    setnum(key, k, fnum(m_, 4)); setnum(key, k + "ci", f"[{fnum(lo, 4)},{fnum(hi, 4)}]")\n                    setnum(key, k + "pe", fp(signflip(d)))\n    with open(os.path.join(a.out, "tab_thrfree.tex"), "w") as f:\n        f.write("\\n".join(rows) + "\\n")\n\n    # ---------------- lambda-rescaling agreement (population-rule test) ----------------\n    if a.preds:\n        for samp in ("frozen", "epoch"):\n            ag, base = [], []\n            for f in glob.glob(os.path.join(a.preds, f"nf_unsw_val-plain-{samp}_mse_s*_rescaled.npy")):\n                s = os.path.basename(f).split("_s")[-1].split("_")[0]\n                g = os.path.join(a.preds, f"nf_unsw_val-freq-{samp}_mse_s{s}.npy")\n                p0 = os.path.join(a.preds, f"nf_unsw_val-plain-{samp}_mse_s{s}.npy")\n                if os.path.exists(g) and os.path.exists(p0):\n                    Rr, Fq, P0 = np.load(f), np.load(g), np.load(p0)\n                    ag.append((Rr == Fq).mean()); base.append((P0 == Fq).mean())\n            if ag:\n                setnum(f"mse-{samp}", "agree", f"{100*np.mean(ag):.1f}\\\\%")\n                setnum(f"mse-{samp}", "agreebase", f"{100*np.mean(base):.1f}\\\\%")\n\n    # ---------------- baselines ----------------\n    rows = []\n    base = [\n        ("PB, squared loss, per-epoch", "rev_nf_unsw_mse.json", "val-plain-epoch", None),\n        ("Cross-entropy (unweighted)", "rev_nf_unsw_ce.json", "ce-plain-none", None),\n        ("Cross-entropy + post-hoc logit adjustment", "rev_nf_unsw_ce.json", "ce-plain-none", "logit_adjusted"),\n        (r"Class-weighted cross-entropy ($-\\log\\pi_c$)", "rev_nf_unsw_ce.json", "ce-freq-none", None),\n        ("Cross-entropy + balanced sampler (per-epoch)", "rev_nf_unsw_ce.json", "ce-plain-epoch", None),\n        ("Extra Trees (tuned)", "rev_nf_unsw_ce.json", "extra_trees", None),\n        ("Random Forest (tuned)", "rev_nf_unsw_ce.json", "rf", None),\n        ("Gradient-boosted trees (tuned)", "rev_nf_unsw_ce.json", "xgboost", None),\n    ]\n    for label, fname, meth, sub in base:\n        recs = list(R.files.get(fname, {}).get(meth, {}).values())\n\n        def m(path):\n            v = [get(r, (sub + "." if sub else "") + path) for r in recs]\n            v = [x for x in v if x is not None]\n            return (f"{np.mean(v):.4f} $\\\\pm$ {np.std(v, ddof=1):.4f}" if len(v) > 1 else TBD)\n        rows.append(" & ".join([label, str(len(recs)) if recs else TBD, m("supported_macro_recall"),\n                                m("macro_f1_supported"), m("detection_f1"), m("false_positive_rate")]) + r" \\\\")\n    with open(os.path.join(a.out, "tab_baselines.tex"), "w") as f:\n        f.write("\\n".join(rows) + "\\n")\n\n    # ---------------- unique flows and run time ----------------\n    rows = []\n    for label, fname, meth in [("natural", "rev_nf_unsw_mse.json", "val-plain-none"),\n                               ("frozen", "rev_nf_unsw_mse.json", "val-plain-frozen"),\n                               ("per-epoch", "rev_nf_unsw_mse.json", "val-plain-epoch"),\n                               ("imp. weights", "rev_nf_unsw_mse.json", "val-plain-iw"),\n                               ("bandit", "rev_nf_unsw_bandit.json", "bandit-plain-epoch")]:\n        recs = list(R.files.get(fname, {}).get(meth, {}).values())\n        if recs and recs[0].get("unique_seen_per_class"):\n            u = np.mean([r["unique_seen_per_class"] for r in recs], 0)\n            t = np.mean([r["train_per_class"] for r in recs], 0)\n            sec = np.mean([r.get("seconds", np.nan) for r in recs])\n            cells = [label] + [f"{100*x/y:.0f}" for x, y in zip(u, t)] + [f"{sec/60:.1f}"]\n            setnum(meth, "normalseen", f"{100*u[0]/t[0]:.0f}\\\\%")\n        else:\n            cells = [label] + [TBD] * 7\n        rows.append(" & ".join(cells) + r" \\\\")\n    with open(os.path.join(a.out, "tab_unique.tex"), "w") as f:\n        f.write("\\n".join(rows) + "\\n")\n\n    # ---------------- replication overlap ----------------\n    if a.processed:\n        fa = [os.path.join(a.processed, f"nf_unsw_regen_{sp}.rows.npy") for sp in ("train", "test")]\n        fb = [os.path.join(a.processed, f"nf_unsw_small2_{sp}.rows.npy") for sp in ("train", "test")]\n        if all(os.path.exists(f) for f in fa + fb):\n            ra = np.concatenate([np.load(f) for f in fa]); rb = np.concatenate([np.load(f) for f in fb])\n            setnum("overlap", "pct", f"{100*np.intersect1d(ra, rb).size/len(rb):.1f}\\\\%")\n        meta = os.path.join(a.processed, "nf_unsw_regen_train.meta.json")\n        if os.path.exists(meta):\n            cc = json.load(open(meta)).get("corpus_counts", {})\n            if cc.get("Malware"):\n                setnum("corpus", "ratio", f"{cc[\'Normal\']/cc[\'Malware\']:,.0f}".replace(",", "\\\\,"))\n\n    # ---------------- numbers file ----------------\n    with open(os.path.join(a.out, "revnums.tex"), "w") as f:\n        f.write("% generated by make_revision_tables.py -- do not edit\\n")\n        for k, v in sorted(nums.items()):\n            if v != TBD:\n                f.write(f"\\\\expandafter\\\\def\\\\csname rv@{k}\\\\endcsname{{{v}}}\\n")\n    print(f"wrote tables to {a.out}; {sum(v != TBD for v in nums.values())} values filled")\n\n\nif __name__ == "__main__":\n    main()\n'

