# STEPS selects which experiment groups this notebook runs, so several notebooks can run in
# parallel without writing the same file:  set e.g. STEPS = 'BD' in the cell before exec(...).
STEPS = globals().get('STEPS', 'ABCGDHEFI')
print('STEPS =', STEPS)

def run(tag, ds, methods, seeds, extra, out):
    if tag.split()[0][0] not in STEPS:
        return
    msg = f'\n######## {tag}  [{time.strftime("%Y-%m-%d %H:%M")}] ########'
    print(msg, flush=True); LOG.write(msg + '\n'); LOG.flush()
    cmd = [sys.executable, 'src/nf_revision.py', '--processed', PROC, '--dataset', ds,
           '--methods', *methods, '--seeds', *seeds, *extra, '--out', f'{OUT}/{out}']
    logf = f'{OUT}/log_{out.replace(".json", "")}.txt'
    with open(logf, 'a') as lf:
        p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                             env={**os.environ, 'TF_CPP_MIN_LOG_LEVEL': '3'})
        tail = []
        for line in p.stdout:
            lf.write(line); lf.flush()
            if not line.startswith(('I0000', 'W0000', 'WARNING: All log')):
                print(line, end='', flush=True)
            tail = (tail + [line])[-40:]
        p.wait()
    if p.returncode:
        print(f'\n!!!! {tag} FAILED (exit {p.returncode}); last lines saved to {logf}:\n' + ''.join(tail), flush=True)

def find_csv(name):
    """Find the corpus on Drive as .csv, or as the .zip downloaded from UQ RDM (unzipped locally)."""
    stem = name.replace('.csv', '')
    c = glob.glob(f'{D}/**/{name}', recursive=True)
    if c:
        return c[0]
    z = [p for p in glob.glob(f'{D}/**/*{stem}*', recursive=True)
         if p.lower().endswith(('.zip', '.csv.gz', '.csv'))]
    if not z:   # UQ RDM zips have hash names (e.g. 9bafce..._MOHANAD_A4706.zip): look inside
        import zipfile
        for p in glob.glob(f'{OUT}/*.zip') + glob.glob(f'{D}/*.zip'):
            try:
                names = zipfile.ZipFile(p).namelist()
            except Exception:
                continue
            if any(stem in os.path.basename(n) and n.lower().endswith('.csv') for n in names):
                print(f'  {name} found inside {os.path.basename(p)}', flush=True)
                z = [p]; break
    if not z:
        return None
    p = z[0]
    if not p.lower().endswith('.zip'):
        return p
    dest = f'/content/data_{stem}'
    if not glob.glob(f'{dest}/**/*.csv', recursive=True):
        os.makedirs(dest, exist_ok=True)
        print(f'  unzipping {p} ...', flush=True)
        subprocess.run(['unzip', '-o', '-q', p, f'*{stem}*.csv', '-d', dest], check=False)
        if not glob.glob(f'{dest}/**/*.csv', recursive=True):
            subprocess.run(['unzip', '-o', '-q', p, '-d', dest], check=True)
    csvs = [c for c in glob.glob(f'{dest}/**/*.csv', recursive=True) if stem in os.path.basename(c)] \
        or glob.glob(f'{dest}/**/*.csv', recursive=True)
    csvs = sorted(csvs, key=os.path.getsize)
    return csvs[-1] if csvs else None

def prep(csvname, ds, seed, cap='400000', floor='1000'):
    if os.path.exists(f'{PROC}/{ds}_train.X.npy'):
        return True
    csv = find_csv(csvname)
    if not csv:
        print(f'  [skip] {csvname} not on Drive -- upload it to run {ds}'); return False
    subprocess.run([sys.executable, 'src/prepare_nf.py', '--input', csv, '--dataset', ds,
                    '--out', f'{PROC}/{ds}', '--cap', cap, '--floor', floor, '--seed', str(seed),
                    '--stream', '--chunksize', '1000000'], check=True)
    return True

